sys_ui_script.script:
var x_37790_appxconnec = x_37790_appxconnec || {};

x_37790_appxconnec.servicenow_adapter = (function () {
	"use strict";

	function createInteractionAjaxCall(callerInfoArr, interactionId) {
		return function (response) {
			var xmltempresult = response.responseXML.getElementsByTagName("result");
			var messagetempres = xmltempresult[0].getAttribute("data");
			var result = JSON.parse(messagetempres);
			result.call_rel_info = callerInfoArr;
			result.interactionId = interactionId;
			document.getElementById("appxcti").contentWindow.postMessage(
				{
					result: result,
				},
				"*"
			);
		};
	}

	return {
		searchEnt: function (requestData) {
			var queryData = {
				command: requestData.command,
				jobuuid: requestData.jobuuid,
				data: {
					interactionId: requestData.data.interactionId,
					entList: requestData.data.snData,
				},
			};
			console.log(queryData);
			var ga = new GlideAjax("AppxGlideData");
			ga.addParam("sysparm_name", "getData");
			ga.addParam("sysparm_querydata", JSON.stringify(queryData));
			ga.getXMLAnswer(function (response) {
				console.log(response);
				var res = JSON.parse(response);

				document.getElementById("appxcti").contentWindow.postMessage(res, "*");
			});
		},
		createEntity: function (requestData) {},
		createInteraction: function (requestData) {
			var ga = new GlideAjax("SNAppxInteractionData");
			ga.addParam("sysparm_name", "createInteraction");
			ga.addParam("sysparm_ctdata", JSON.stringify(requestData));
			ga.getXMLAnswer(function (response) {
				var res = JSON.parse(response);

				document.getElementById("appxcti").contentWindow.postMessage(res, "*");
			});
		},
		updateInteraction: function (requestData) {
			var ga = new GlideAjax("SNAppxInteractionData");
			ga.addParam("sysparm_name", "updateInteraction");
			ga.addParam("sysparm_ctdata", JSON.stringify(requestData));
			ga.getXMLAnswer(function (response) {
				console.log(response);
				var res = JSON.parse(response);
				document.getElementById("appxcti").contentWindow.postMessage(res, "*");
				return;
			});
		},
		type: "servicenow_adapter",
	};
})();
